<script setup lang="ts">
import Select from './ui/Select.vue'
import { onMounted,reactive,ref,watch } from 'vue'
import { api,errorText } from '../api'
import { useLoad } from '../composables'
import type { Page,Grant,User } from '../types'
import PageState from './PageState.vue'
import PaginationBar from './PaginationBar.vue'
const props=defineProps<{targetId:string}>(),page=ref(0),users=ref<User[]>([]),userPage=ref(0),userTotal=ref(0),loadingUsers=ref(false)
const {data,loading,error,load}=useLoad(()=>api<Page<Grant>>(`/targets/${props.targetId}/access?page=${page.value}&size=20`))
const form=reactive({userId:'',canRead:false,canOperate:false,reason:''}),busy=ref(false),selecting=ref(false),selectionReady=ref(false),saveError=ref(''),saved=ref(false)
let selection=0
watch(()=>form.canRead,v=>{if(!v)form.canOperate=false})
async function loadUsers(){loadingUsers.value=true;try{const p=await api<Page<User>>(`/admin/users?page=${userPage.value}&size=100`);users.value.push(...p.items);userTotal.value=p.total;userPage.value++}catch(e){saveError.value=errorText(e)}finally{loadingUsers.value=false}}
onMounted(()=>{void load();void loadUsers()})
async function selectUser(){const generation=++selection;saved.value=false;selectionReady.value=false;saveError.value='';form.reason='';if(!form.userId)return;selecting.value=true;try{const result=await api<Page<Grant>>(`/targets/${props.targetId}/access?userId=${encodeURIComponent(form.userId)}&size=1`);if(generation===selection){const g=result.items[0];form.canRead=g?.canRead??false;form.canOperate=g?.canOperate??false;selectionReady.value=true}}catch(e){if(generation===selection)saveError.value=errorText(e)}finally{if(generation===selection)selecting.value=false}}
function edit(g:Grant){if(!users.value.some(u=>u.id===g.userId))users.value.push({id:g.userId,username:g.username,displayName:g.displayName,roles:[]});form.userId=g.userId;void selectUser()}
async function save(){busy.value=true;saveError.value='';saved.value=false;try{await api(`/targets/${props.targetId}/access/${form.userId}`,{method:'PUT',body:{canRead:form.canRead,canOperate:form.canOperate,reason:form.reason}});form.reason='';saved.value=true;await load()}catch(e){saveError.value=errorText(e)}finally{busy.value=false}}
</script>
<template><div class="panel-heading"><div><h2>目标访问权限</h2><p>读取授权控制可见范围；处理事故还需要 ON_CALL 角色与操作授权。</p></div></div><div class="form-panel compact-form"><div v-if="saveError" class="error-message" role="alert">{{ saveError }}</div><div v-if="saved" class="success-message" role="status">目标授权已保存。</div><form @submit.prevent="save"><label>选择用户<Select v-model="form.userId" aria-label="授权用户" required :disabled="busy||loadingUsers" :options="[{value:'',label:'请选择用户',disabled:true},...users.map(u=>({value:u.id,label:u.displayName+' · '+u.username}))]" @change="selectUser" /></label><button v-if="users.length<userTotal" type="button" class="text-button" :disabled="loadingUsers" @click="loadUsers">{{ loadingUsers?'加载中…':'加载更多用户' }}</button><div v-if="form.userId" class="permission-options"><label class="check-label"><input v-model="form.canRead" type="checkbox" :disabled="selecting||busy">允许读取目标、检查和事故</label><label class="check-label"><input v-model="form.canOperate" type="checkbox" :disabled="!form.canRead||selecting||busy">允许处理事故（同时需要值班角色）</label></div><label v-if="form.userId">变更理由<input v-model="form.reason" required maxlength="500" :disabled="selecting||busy" placeholder="说明授权或撤销的原因"></label><div v-if="form.userId" class="form-actions"><button class="btn primary" :disabled="busy||selecting||!selectionReady">{{ busy?'保存中…':selecting?'读取现有授权…':'保存授权' }}</button></div></form></div><PageState :loading="loading&&!data" :error="error" :empty="!!data&&!data.items.length" title="尚未分配目标权限" description="通过上方表单为用户分配读取或操作权限。" @retry="load"><template v-if="data"><div class="table-scroll"><table><thead><tr><th>用户</th><th>读取权限</th><th>操作权限</th><th>操作</th></tr></thead><tbody><tr v-for="g in data.items" :key="g.userId"><td><strong>{{ g.displayName }}</strong><small class="cell-note">{{ g.username }}</small></td><td>{{ g.canRead?'允许':'未授权' }}</td><td>{{ g.canOperate?'允许':'未授权' }}</td><td><button class="text-button" @click="edit(g)">编辑授权</button></td></tr></tbody></table></div><PaginationBar :page="page" :size="20" :total="data.total" @change="p=>{page=p;load()}" /></template></PageState></template>
